import React, { useState, useEffect, useRef } from "react";
import { getMatches, getTeamComparison } from "../api";

const HistoryList = ({ title, matches }) => (
  <div className="bg-gray-800/40 p-8 rounded-[32px] border border-white/5 h-full">
    <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-6 text-center">
      {title}
    </h3>
    <div className="space-y-4">
      {matches && matches.length > 0 ? (
        matches.map((m, i) => (
          <div
            key={i}
            className="flex items-center justify-between gap-4 bg-black/20 p-4 rounded-2xl border border-white/5"
          >
            <div
              className={`text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-tighter ${m.is_home ? "bg-blue-500/20 text-blue-400 border border-blue-500/30" : "bg-purple-500/20 text-purple-400 border border-purple-500/30"}`}
            >
              {m.is_home ? "ДОМА" : "ГОСТИ"}
            </div>
            <div className="flex items-center gap-4 flex-grow">
              <img
                src={m.opponent_logo}
                alt=""
                className="w-8 h-8 object-contain"
              />
              <span className="text-sm md:text-base font-bold text-white truncate max-w-[180px]">
                {m.opponent}
              </span>
            </div>
            <div className="flex items-center gap-4">
              <span className="text-base md:text-lg font-black text-white font-mono tracking-tighter">
                {m.score}
              </span>
              <span
                className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs font-black shadow-lg ${m.res === "W" ? "bg-green-500 text-white" : m.res === "L" ? "bg-red-600 text-white" : "bg-yellow-500 text-black"}`}
              >
                {m.res}
              </span>
            </div>
          </div>
        ))
      ) : (
        <p className="text-sm text-gray-600 italic text-center py-10">
          Данные не найдены
        </p>
      )}
    </div>
  </div>
);

const ResultCircle = ({ res }) => {
  const colors = { W: "bg-green-500", D: "bg-yellow-500", L: "bg-red-600" };
  return (
    <span
      className={`${colors[res]} w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-black text-white shadow-lg`}
    >
      {res}
    </span>
  );
};

const StatBar = ({ label, h, a, reverse, color }) => {
  const isHomeBetter = reverse ? h < a : h > a;
  const total = (parseFloat(h) || 0) + (parseFloat(a) || 0) || 1;
  return (
    <div className="relative group">
      <div className="flex justify-between items-end mb-2">
        <span className="text-2xl font-black text-white">
          {(parseFloat(h) || 0).toFixed(2)}
        </span>
        <span className="text-[10px] font-black text-white uppercase tracking-widest mb-1 text-center">
          {label}
        </span>
        <span className="text-2xl font-black text-white">
          {(parseFloat(a) || 0).toFixed(2)}
        </span>
      </div>
      <div className="h-2.5 w-full bg-gray-800 rounded-full flex overflow-hidden p-0.5 border border-gray-700">
        <div
          className={`h-full rounded-full transition-all duration-1000 ${isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${((parseFloat(h) || 0) / total) * 100}%` }}
        ></div>
        <div
          className={`h-full rounded-full transition-all duration-1000 ${!isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${((parseFloat(a) || 0) / total) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

function ComparePage() {
  const [allTeams, setAllTeams] = useState([]);
  const [team1, setTeam1] = useState("");
  const [team2, setTeam2] = useState("");

  const [suggestions1, setSuggestions1] = useState([]);
  const [suggestions2, setSuggestions2] = useState([]);
  const [showSugg1, setShowSugg1] = useState(false);
  const [showSugg2, setShowSugg2] = useState(false);

  const [comparisonData, setComparisonData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const input1Ref = useRef(null);
  const input2Ref = useRef(null);
  const container1Ref = useRef(null);
  const container2Ref = useRef(null);

  useEffect(() => {
    const fetchTeams = async () => {
      try {
        const data = await getMatches(null);
        const teamMap = new Map();
        data.forEach((m) => {
          if (m.homeTeam) {
            teamMap.set(m.homeTeam.name, m.homeTeam.logo_url);
            if (m.homeTeam.name_ru)
              teamMap.set(m.homeTeam.name_ru, m.homeTeam.logo_url);
          }
          if (m.awayTeam) {
            teamMap.set(m.awayTeam.name, m.awayTeam.logo_url);
            if (m.awayTeam.name_ru)
              teamMap.set(m.awayTeam.name_ru, m.awayTeam.logo_url);
          }
        });
        const teamsArray = Array.from(teamMap.entries()).map(
          ([name, logo]) => ({ name, logo }),
        );
        setAllTeams(teamsArray.sort((a, b) => a.name.localeCompare(b.name)));
      } catch (e) {
        console.error("Failed to load teams", e);
      }
    };
    fetchTeams();

    const handleClickOutside = (e) => {
      if (container1Ref.current && !container1Ref.current.contains(e.target))
        setShowSugg1(false);
      if (container2Ref.current && !container2Ref.current.contains(e.target))
        setShowSugg2(false);
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleCompare = async (t1 = team1, t2 = team2) => {
    if (!t1 || !t2) {
      setError("Выберите обе команды");
      return;
    }
    setLoading(true);
    setError("");
    setShowSugg1(false);
    setShowSugg2(false);
    const data = await getTeamComparison(t1, t2);
    if (data) setComparisonData(data);
    else setError("Команды не найдены");
    setLoading(false);
  };

  const handleInputChange = (val, setTeam, setSugg, setShow) => {
    setTeam(val);
    if (val.length > 0) {
      const filtered = allTeams
        .filter((t) => t.name.toLowerCase().includes(val.toLowerCase()))
        .slice(0, 10);
      setSugg(filtered);
      setShow(true);
    } else {
      setShow(false);
    }
  };

  const selectSuggestion = (teamObj, setTeam, setShow, nextRef = null) => {
    setTeam(teamObj.name);
    setShow(false);
    if (nextRef) nextRef.current.focus();
    else handleCompare(team1, teamObj.name);
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-8 text-white font-sans">
      <div className="bg-gray-900 p-8 rounded-[32px] border border-gray-800 shadow-2xl mb-12">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="w-full md:w-2/5 relative" ref={container1Ref}>
            <input
              ref={input1Ref}
              type="text"
              value={team1}
              onChange={(e) =>
                handleInputChange(
                  e.target.value,
                  setTeam1,
                  setSuggestions1,
                  setShowSugg1,
                )
              }
              onKeyDown={(e) => e.key === "Enter" && input2Ref.current.focus()}
              autoComplete="one-time-code"
              placeholder="Первая команда..."
              className="w-full bg-gray-950 border border-gray-800 rounded-2xl py-5 px-8 text-lg text-white focus:outline-none focus:border-red-600 transition-all placeholder:text-gray-800"
            />
            {showSugg1 && suggestions1.length > 0 && (
              <ul className="absolute top-full left-0 right-0 mt-3 bg-gray-950 border border-gray-800 rounded-2xl shadow-2xl z-[100] overflow-hidden">
                {suggestions1.map((s, i) => (
                  <li
                    key={i}
                    onClick={() =>
                      selectSuggestion(s, setTeam1, setShowSugg1, input2Ref)
                    }
                    className="flex items-center gap-4 px-6 py-4 hover:bg-red-600 cursor-pointer transition-colors border-b border-gray-900 last:border-0"
                  >
                    <img
                      src={s.logo}
                      alt=""
                      className="w-8 h-8 object-contain"
                    />
                    <span className="text-base font-bold">{s.name}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>

          <div className="flex-shrink-0 w-14 h-14 bg-gray-800 rounded-full flex items-center justify-center border border-gray-700 text-gray-500 font-black italic">
            VS
          </div>

          <div className="w-full md:w-2/5 relative" ref={container2Ref}>
            <input
              ref={input2Ref}
              type="text"
              value={team2}
              onChange={(e) =>
                handleInputChange(
                  e.target.value,
                  setTeam2,
                  setSuggestions2,
                  setShowSugg2,
                )
              }
              onKeyDown={(e) => e.key === "Enter" && handleCompare()}
              autoComplete="one-time-code"
              placeholder="Вторая команда..."
              className="w-full bg-gray-950 border border-gray-800 rounded-2xl py-5 px-8 text-lg text-white focus:outline-none focus:border-red-600 transition-all placeholder:text-gray-800"
            />
            {showSugg2 && suggestions2.length > 0 && (
              <ul className="absolute top-full left-0 right-0 mt-3 bg-gray-950 border border-gray-800 rounded-2xl shadow-2xl z-[100] overflow-hidden">
                {suggestions2.map((s, i) => (
                  <li
                    key={i}
                    onClick={() => selectSuggestion(s, setTeam2, setShowSugg2)}
                    className="flex items-center gap-4 px-6 py-4 hover:bg-red-600 cursor-pointer transition-colors border-b border-gray-900 last:border-0"
                  >
                    <img
                      src={s.logo}
                      alt=""
                      className="w-8 h-8 object-contain"
                    />
                    <span className="text-base font-bold">{s.name}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>

      {loading && (
        <div className="text-center py-20 text-red-600 font-black animate-pulse">
          ANALYZING TEAMS...
        </div>
      )}

      {comparisonData && !loading && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="flex flex-col md:flex-row justify-between items-center bg-gray-900 p-8 md:p-12 rounded-[40px] border border-gray-800 shadow-2xl relative overflow-hidden mb-10">
            <div className="flex flex-col items-center w-full md:w-2/5">
              <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-4 py-1.5 rounded-full mb-4 tracking-widest border border-gray-700 uppercase">
                ELO: {Math.round(comparisonData.team1.elo)}
              </div>
              <img
                src={comparisonData.team1.logo_url}
                className="h-36 w-36 object-contain mb-4 drop-shadow-2xl"
                alt=""
              />
              <h2 className="text-3xl font-black uppercase tracking-tighter text-center">
                {comparisonData.team1.name}
              </h2>
              <div className="flex gap-2 mt-4">
                {comparisonData.team1.stats.form.map((r, i) => (
                  <ResultCircle key={i} res={r} />
                ))}
              </div>
            </div>
            <span className="text-7xl font-black text-white opacity-10 italic my-8 md:my-0 uppercase tracking-tighter">
              VS
            </span>
            <div className="flex flex-col items-center w-full md:w-2/5">
              <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-4 py-1.5 rounded-full mb-4 tracking-widest border border-gray-700 uppercase">
                ELO: {Math.round(comparisonData.team2.elo)}
              </div>
              <img
                src={comparisonData.team2.logo_url}
                className="h-36 w-36 object-contain mb-4 drop-shadow-2xl"
                alt=""
              />
              <h2 className="text-3xl font-black uppercase tracking-tighter text-center">
                {comparisonData.team2.name}
              </h2>
              <div className="flex gap-2 mt-4">
                {comparisonData.team2.stats.form.map((r, i) => (
                  <ResultCircle key={i} res={r} />
                ))}
              </div>
            </div>
          </div>

          {comparisonData.prediction && (
            <div className="bg-gray-900 rounded-[32px] p-8 md:p-12 mb-10 border border-gray-800 shadow-2xl relative overflow-hidden">
              <h2 className="text-sm md:text-base font-black text-white uppercase tracking-[0.3em] mb-10 text-center">
                Анализ Нейросети
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-stretch relative z-10">
                <div className="bg-black/40 p-6 rounded-3xl border border-gray-800 flex flex-col justify-center">
                  <div className="flex justify-between mb-3 text-xs font-black uppercase text-white">
                    <span>П1: {comparisonData.prediction.prob_home}%</span>
                    <span>X: {comparisonData.prediction.prob_draw}%</span>
                    <span>П2: {comparisonData.prediction.prob_away}%</span>
                  </div>
                  <div className="h-5 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                    <div
                      className="bg-green-500 h-full rounded-l-full"
                      style={{
                        width: `${comparisonData.prediction.prob_home}%`,
                      }}
                    ></div>
                    <div
                      className="bg-yellow-500 h-full"
                      style={{
                        width: `${comparisonData.prediction.prob_draw}%`,
                      }}
                    ></div>
                    <div
                      className="bg-red-600 h-full rounded-r-full"
                      style={{
                        width: `${comparisonData.prediction.prob_away}%`,
                      }}
                    ></div>
                  </div>
                </div>
                <div className="flex flex-col items-center justify-center p-6 bg-gray-800/30 rounded-3xl border border-gray-800 text-center">
                  <span className="text-[10px] font-black text-white opacity-60 uppercase mb-4">
                    Прогноз счета
                  </span>
                  <span className="text-6xl font-black text-white italic tracking-tighter leading-none">
                    {comparisonData.prediction.exact_score}
                  </span>
                </div>
                <div className="bg-black/40 p-6 rounded-3xl border border-gray-800 flex flex-col justify-center">
                  <div className="flex justify-between mb-3 text-xs font-black uppercase text-white">
                    <span>
                      БОЛЬШЕ: {comparisonData.prediction.total_over_2_5}%
                    </span>
                    <span>
                      МЕНЬШЕ:{" "}
                      {(100 - comparisonData.prediction.total_over_2_5).toFixed(
                        1,
                      )}
                      %
                    </span>
                  </div>
                  <div className="h-5 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                    <div
                      className="bg-red-600 h-full rounded-l-full"
                      style={{
                        width: `${comparisonData.prediction.total_over_2_5}%`,
                      }}
                    ></div>
                    <div
                      className="bg-yellow-500 h-full rounded-r-full"
                      style={{
                        width: `${(100 - comparisonData.prediction.total_over_2_5).toFixed(1)}%`,
                      }}
                    ></div>
                  </div>
                </div>
              </div>
            </div>
          )}

          <div className="bg-gray-900 rounded-[32px] p-8 md:p-12 border border-gray-800 shadow-xl mb-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-20">
              <div className="space-y-8">
                <div className="text-center mb-6">
                  <span className="inline-block bg-green-500/10 border border-green-500/30 text-green-500 text-[11px] font-black uppercase tracking-widest px-6 py-2 rounded-full">
                    Атака (Last 5)
                  </span>
                </div>
                <StatBar
                  label="В среднем забито"
                  h={comparisonData.team1.stats.gf}
                  a={comparisonData.team2.stats.gf}
                  color="bg-green-500"
                />
                <StatBar
                  label="Созданный xG"
                  h={comparisonData.team1.stats.xg_for}
                  a={comparisonData.team2.stats.xg_for}
                  color="bg-green-500"
                />
                <StatBar
                  label="Глубокие атаки"
                  h={comparisonData.team1.stats.deep}
                  a={comparisonData.team2.stats.deep}
                  color="bg-green-500"
                />
              </div>
              <div className="space-y-8">
                <div className="text-center mb-6">
                  <span className="inline-block bg-red-600/10 border border-red-600/30 text-red-500 text-[11px] font-black uppercase tracking-widest px-6 py-2 rounded-full">
                    Оборона (Last 5)
                  </span>
                </div>
                <StatBar
                  label="В среднем пропущено"
                  h={comparisonData.team1.stats.ga}
                  a={comparisonData.team2.stats.ga}
                  reverse
                  color="bg-red-600"
                />
                <StatBar
                  label="Допущенный xG"
                  h={comparisonData.team1.stats.xg_against}
                  a={comparisonData.team2.stats.xg_against}
                  reverse
                  color="bg-red-600"
                />
                <StatBar
                  label="Прессинг (PPDA)"
                  h={comparisonData.team1.stats.ppda}
                  a={comparisonData.team2.stats.ppda}
                  reverse
                  color="bg-red-600"
                />
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <HistoryList
              title={`История: ${comparisonData.team1.name}`}
              matches={comparisonData.team1.history}
            />
            <HistoryList
              title={`История: ${comparisonData.team2.name}`}
              matches={comparisonData.team2.history}
            />
          </div>
        </div>
      )}
    </div>
  );
}

export default ComparePage;
